enum SM64BowserTailAnchorBehavior { static func update(action:SM64BowserTailAnchorAction,timer:Int32,parentAction:Int32,parentIntangibleTimer:Int32,collided:Bool)->SM64BowserTailAnchorOutput{var a=action;var tangible=true;var parentTimer=parentIntangibleTimer;if action == .tangible{if parentAction == 19{parentTimer = -1}else if collided{parentTimer=0;a = .intangible}else{parentTimer = -1}}else if action == .collisionCooldown{if timer > 30{a = .tangible}}else{tangible=false;if parentAction == 19{parentTimer = -1;a = .tangible;tangible=true}};return .init(action:a,tangible:tangible && a != .intangible,parentIntangibleTimer:parentTimer,parentRelativeX:90)} }
